ROUTES = (
    (0x54EC490, 0xA0, 0x73DA48),
    (0x54EC490, 0xA8, 0x73DA50),
    (0x54EC490, 0xB0, 0x73DA58),
)


def verify_native(read, base):
    for rva, expected in SPANS:
        if read(base + rva, len(expected)) != expected:
            raise ValueError("Native shared entity/ball world-coordinate basis changed")
    for table, offset, target in ROUTES:
        if struct.unpack("<Q", read(base + table + offset, 8))[0] != base + target:
            raise ValueError("Named world-coordinate getter route changed")
